import {ACCOUNT_ID} from './poller.mjs';
import {ensureOperator} from './operator-ui.mjs';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const stamp=t=>t?new Date(t).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false}):'—';
const labels={confirmed:'已回读确认',partial:'部分成功',uncertain:'结果待核实',submitting:'正在提交',rejected:'提交前未通过',cancelled:'未提交已取消',resolved:'已按平台现状结束',planned:'准备中','not-submitted':'尚未提交'};
const reasons={SPEND_BELOW_THRESHOLD:'未到预算80%',WAITING_FOR_DEFERRED_ROI:'预算已追加，等待补调ROI',COLD_ROI_CATCH_UP:'补调先前约定的ROI',WINDOW_DATA_BUDGET_ONLY:'窗口数据不足，仅按阈值加预算',ROI_INTERVAL_NOT_READY:'ROI修改间隔未满',PREVIOUS_WRITE_UNRESOLVED:'上次操作结果待核实',PLAN_PAUSED:'计划已暂停',GROUP_BUDGET_EXHAUSTED:'计划组预算耗尽',AUDIT_OR_DELIVERY_STATE_UNVERIFIED:'审核或投放状态待核实',RECOVERY_OUTCOME_STILL_UNKNOWN:'提交结果仍不明确，不能补做或解除阻塞',RECOVERY_ALREADY_RESOLVED:'该记录已处理，无需再次提交',RECOVERY_STEP_NOT_RETRYABLE:'这一步不符合安全补做条件',RECOVERY_PLAN_CHANGED:'计划已变化，请重新核实',RECOVERY_INTENT_EXPIRED:'原操作已过时段或跨日，请核实后按平台现状结束',RECOVERY_CONFIRMATION_INVALID:'确认已失效，请重新核对'};
async function request(action,body){const response=await fetch('/lan-api/operation/automation-'+action,{method:body?'POST':'GET',cache:'no-store',...(body?{headers:{'Content-Type':'application/json'},body:JSON.stringify({accountId:ACCOUNT_ID,...body})}:{})});const value=await response.json();if(!response.ok)throw Error(reasons[value.error?.code]||value.error?.message||'请求失败');return value;}
export function initializeAutomationRecovery(notify){
 const anchor=document.getElementById('operator-login');if(!anchor||document.getElementById('automation-history'))return;
 const button=document.createElement('button');button.id='automation-history';button.type='button';button.textContent='自动化记录';button.style.cssText='display:inline-flex;align-items:center;white-space:nowrap;font-size:12px;padding:7px 12px;border:1px solid #cad8f5;border-radius:6px;color:#315de2;background:#f4f7ff';anchor.after(button);button.onclick=()=>void openAutomationRecovery().catch(e=>notify(e.message));
}
export async function openAutomationRecovery(){
 if(!await ensureOperator({readOnly:true}))return;
 const dialog=document.createElement('dialog');dialog.className='operation-dialog';dialog.setAttribute('aria-label','自动化记录与恢复');dialog.style.cssText='width:min(960px,94vw);max-height:90vh;overflow:auto';
 dialog.innerHTML='<header><h2>自动化记录与恢复</h2><button type="button" data-close aria-label="关闭自动化记录">×</button></header><p>先核实平台结果，再选择单步补做或按平台现状结束。已成功步骤不会重复提交。</p><p role="alert" class="operation-error"></p><div data-content></div><footer><button type="button" data-refresh>刷新记录</button><button type="button" data-close>关闭</button></footer>';
 document.body.append(dialog);dialog.showModal();const content=dialog.querySelector('[data-content]'),error=dialog.querySelector('.operation-error');let busy=false,preview=null;
 const work=async fn=>{if(busy)return;busy=true;error.textContent='';dialog.querySelectorAll('button').forEach(b=>b.disabled=true);try{await fn();}catch(e){error.textContent=e.message;}finally{busy=false;dialog.querySelectorAll('button').forEach(b=>b.disabled=false);}};
 const overview=async()=>{preview=null;const data=await request('history');content.innerHTML=`<h3>报名计划</h3><div style="overflow:auto"><table style="min-width:560px;width:100%"><thead><tr><th>计划</th><th>ROI / 预算</th><th>当前判断</th></tr></thead><tbody>${data.plans.map(p=>`<tr><td>${esc(p.name)}<br><small>${esc(p.id)}</small></td><td>${esc(p.roi)} / ${esc(p.budget)}元</td><td>${esc(reasons[p.decision?.reason]||p.decision?.reason||'等待检查')}${p.pendingRoi?`<br>待补${p.pendingRoi.queue?.length||1}笔，下次ROI：${esc(p.pendingRoi.target)}`:''}<br><small>核验：${stamp(p.readAt)}</small></td></tr>`).join('')}</tbody></table></div><h3>执行记录</h3>${data.jobs.length?data.jobs.map(j=>`<article style="border-top:1px solid #ddd;padding:12px 0"><b>${esc(j.name||j.planId)}</b> · ${esc(labels[j.status]||j.status)}<br><small>${stamp(j.startedAt)}</small><p>${j.steps.map(s=>`${s.field==='roi'?'ROI':s.field==='budget'?'预算':'起量'} ${esc(s.before??'—')} → ${esc(s.target)}（${esc(labels[s.status]||s.status)}）`).join('；')}</p>${j.held?`<button type="button" data-review="${esc(j.id)}">核实平台结果</button>`:''}</article>`).join(''):'<p>尚无自动执行记录。上方显示最新检查结果。</p>'}`;};
 const detail=j=>{preview=null;content.innerHTML=`<h3>${esc(j.name||j.planId)}</h3><p>${esc(labels[j.status]||j.status)}</p><ol>${j.steps.map(s=>`<li>${s.field==='roi'?'ROI':s.field==='budget'?'预算':'起量'}：${esc(s.before??'—')} → ${esc(s.target)}，${esc(labels[s.status]||s.status)}</li>`).join('')}</ol>${j.review?`<p>平台当前：ROI ${esc(j.review.current.roi)}，预算 ${esc(j.review.current.budget)}元；${esc(j.review.current.status)}。核实于 ${stamp(j.review.at)}</p>`:''}${j.review?.unknown?'<p>仍有已经提交但结果未确认的步骤，暂不开放补做或解除阻塞。可稍后重新核实。</p>':''}<div style="display:flex;gap:8px;flex-wrap:wrap">${j.held?`<button data-review="${esc(j.id)}">再次核实</button>`:''}${j.held&&j.review?.retryStep>=0?`<button data-prepare="step" data-job="${esc(j.id)}" data-index="${j.review.retryStep}">核对单步补做</button>`:''}${j.held&&j.review?.canResolve?`<button data-prepare="resolve" data-job="${esc(j.id)}">核对按现状结束并解除阻塞</button>`:''}<button data-back>返回记录</button></div>`;};
 dialog.addEventListener('click',event=>{const b=event.target.closest('button');if(!b||busy)return;
  if(b.hasAttribute('data-close')){dialog.close();return;}
  if(b.hasAttribute('data-refresh')||b.hasAttribute('data-back'))void work(overview);
  if(b.dataset.review)void work(async()=>detail(await request('recheck',{id:b.dataset.review})));
  if(b.dataset.prepare)void work(async()=>{if(!await ensureOperator())return;preview=await request('prepare',{id:b.dataset.job,kind:b.dataset.prepare,index:Number(b.dataset.index)});content.innerHTML=`<h3>请确认本次处理</h3><p>${esc(preview.description)}</p><p>确认有效期60秒；计划变化后需重新核对。</p><button data-confirm class="primary">${preview.kind==='resolve'?'确认按现状结束':'确认只补做这一步'}</button> <button data-back>取消并返回</button>`;});
  if(b.hasAttribute('data-confirm')&&preview)void work(async()=>{const token=preview.token;preview=null;try{detail(await request('commit',{token,confirmed:true}));}catch(e){content.innerHTML='<p>本次确认已用完。请返回记录核实结果，不会自动重复提交。</p><button data-back>返回记录</button>';throw e;}});
 });
 dialog.addEventListener('cancel',event=>{if(busy)event.preventDefault();});dialog.addEventListener('close',()=>dialog.remove());await work(overview);
}
